async function readImportRows(file,type){if(!window.XLSX)throw new Error('Modul pembaca Excel belum termuat.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'}),preferred=type==='employee'?'Karyawan':'Armada',sheet=workbook.Sheets[preferred]||workbook.Sheets[workbook.SheetNames[0]];return XLSX.utils.sheet_to_json(sheet,{defval:''}).filter(row=>{const first=String(type==='employee'?row.nama_lengkap:row.plat_nomor).trim();return first&&!/^contoh/i.test(first)})}
async function importEmployees(rows,session){const results=[];for(let index=0;index<rows.length;index++){const row=rows[index],fullName=String(row.nama_lengkap||'').trim(),position=String(row.jabatan||'').trim(),password=String(row.kata_sandi_awal||'');if(!fullName||!position||password.length<8){results.push({ok:false,row:index+2,error:'Nama, jabatan, dan kata sandi minimal 8 karakter wajib diisi.'});continue}const {data,error}=await window.hmaSupabase.functions.invoke('create-employee',{body:{fullName,position,password},headers:{Authorization:`Bearer ${session.access_token}`}});if(error){let message='Gagal membuat akun.';try{message=(await error.context.json()).error||message}catch{}results.push({ok:false,row:index+2,error:message})}else results.push({ok:true,row:index+2,code:data.employeeCode})}return results}
async function importFleets(rows){const aliases={'siap operasi':'active','aktif':'active','dalam perawatan':'maintenance','perawatan':'maintenance','tidak aktif':'inactive'};const valid=['active','maintenance','inactive'],payload=[],errors=[];rows.forEach((row,index)=>{const plate=String(row.plat_nomor||'').trim().toUpperCase().replace(/\s+/g,' '),model=String(row.jenis_model||'').trim(),raw=String(row.status||'active').trim().toLowerCase(),fleetStatus=aliases[raw]||raw,odometer=Number(row.odometer)||0;if(!plate||!model||!valid.includes(fleetStatus)||odometer<0)errors.push({ok:false,row:index+2,error:'Plat, model, odometer, atau status tidak valid.'});else payload.push({plate_no:plate,model,current_odometer:odometer,status:fleetStatus})});if(payload.length){const {data,error}=await window.hmaSupabase.from('vehicles').upsert(payload,{onConflict:'plate_no'}).select('plate_no');if(error)throw error;(data||[]).forEach(item=>errors.push({ok:true,plate:item.plate_no}))}return errors}
document.getElementById('importForm').addEventListener('submit',async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Mengimpor…';importFeedback.hidden=true;try{if(!await ensureAdminSession())throw new Error('Sesi admin berakhir. Silakan masuk kembali.');const type=document.getElementById('importType').value,rows=await readImportRows(document.getElementById('importFile').files[0],type);if(!rows.length)throw new Error('Tidak ada baris data yang dapat diimpor.');const {data:{session}}=await window.hmaSupabase.auth.getSession();const results=type==='employee'?await importEmployees(rows,session):await importFleets(rows),success=results.filter(x=>x.ok).length,failed=results.length-success;if(type==='employee')await loadTeam();else await loadFleets();importFeedback.textContent=`Selesai: ${success} berhasil, ${failed} gagal.${failed?' Periksa format pada baris '+results.filter(x=>!x.ok).map(x=>x.row).join(', ')+'.':''}`;importFeedback.style.background=failed?'#fff5e2':'#edf8f7';importFeedback.style.color=failed?'#9a6200':'#087c74';importFeedback.hidden=false;if(!failed){setTimeout(closeImportModal,1400);notify(`✓ ${success} data berhasil diimpor.`)}}catch(error){importFeedback.textContent=error.code==='42501'?'Izin import armada belum aktif di server.':(error.message||'Import data gagal.');importFeedback.style.background='#fff0f0';importFeedback.style.color='#c33';importFeedback.hidden=false}finally{submit.disabled=false;submit.textContent='Mulai import'}});
const employeeResetModal=document.getElementById('employeeResetModal');
function closeEmployeeReset(){employeeResetModal.close();document.getElementById('employeeResetForm').reset();backdrop.classList.remove('show')}
async function openEmployeeReset(id,code,name){if(!await ensureAdminSession()){closeEmployeeReset();notify('Sesi admin berakhir. Silakan masuk kembali.');openAdminLogin();return}document.getElementById('employeeResetForm').reset();document.getElementById('resetEmployeeId').value=id;document.getElementById('resetEmployeeName').value=`${code} · ${name}`;employeeResetModal.showModal();backdrop.classList.add('show')}
document.querySelectorAll('[data-close-employee-reset]').forEach(button=>button.addEventListener('click',closeEmployeeReset));
async function manageEmployee(body){if(!await ensureAdminSession()){closeEmployeeReset();openAdminLogin();throw new Error('Sesi admin berakhir. Silakan masuk kembali.')}const {data:{session}}=await window.hmaSupabase.auth.getSession();if(!session?.access_token)throw new Error('Sesi admin berakhir. Silakan masuk kembali.');const {data,error}=await window.hmaSupabase.functions.invoke('manage-employee',{body,headers:{Authorization:`Bearer ${session.access_token}`}});if(error){let detail='Akun belum dapat dikelola.';try{const response=await error.context.json();detail=response.error||detail}catch{}throw new Error(detail)}return data}
document.getElementById('employeeResetForm').addEventListener('submit',async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('[type="submit"]');submit.disabled=true;try{const data=await manageEmployee({action:'reset_password',employeeId:document.getElementById('resetEmployeeId').value,password:document.getElementById('resetEmployeePassword').value});closeEmployeeReset();notify(`✓ Berhasil — ${data.message||'kata sandi sudah diperbarui.'}`)}catch(error){notify(error.message)}finally{submit.disabled=false}});
document.addEventListener('click',async e=>{const reset=e.target.closest('.employee-reset-action');if(reset){await openEmployeeReset(reset.dataset.id,reset.dataset.code,reset.dataset.name);return}const remove=e.target.closest('.employee-delete-action');if(!remove)return;if(!await ensureAdminSession()){notify('Sesi admin berakhir. Silakan masuk kembali.');openAdminLogin();return}if(!confirm(`Hapus akun ${remove.dataset.code} · ${remove.dataset.name}? Data profil akun akan dihapus permanen.`))return;remove.disabled=true;try{const data=await manageEmployee({action:'delete',employeeId:remove.dataset.id});notify(`✓ Berhasil — ${data.message||'akun sudah dihapus.'}`);await loadTeam()}catch(error){notify(error.message)}finally{remove.disabled=false}});
const adminLoginModal=document.getElementById('adminLoginModal');
function closeAdminLogin(force=false){if(document.body.classList.contains('login-required')&&!force)return;adminLoginModal.close();backdrop.classList.remove('show')}
function openAdminLogin(){document.body.classList.add('login-required');document.querySelectorAll('[data-close-admin-login]').forEach(button=>button.hidden=true);if(!adminLoginModal.open)adminLoginModal.showModal();backdrop.classList.add('show')}
function finishLogin(){document.body.classList.remove('login-required');document.querySelectorAll('[data-close-admin-login]').forEach(button=>button.hidden=false);closeAdminLogin(true)}
function returnToLogin(){state.team=[];state.reports=[];state.fleets=[];state.fuels=[];state.transactions=[];state.attendance=[];state.payroll=[];render();[reportModal,fuelModal,fleetModal,fuelTypeModal,fuelPriceModal,salaryModal,employeeModal,employeeResetModal,importModal,passwordRecoveryModal].forEach(dialog=>{if(dialog?.open)dialog.close()});document.getElementById('adminLoginForm').reset();document.getElementById('adminLoginFeedback').hidden=true;if(!adminLoginModal.open)openAdminLogin()}
async function refreshAdminIdentity(){const name=document.getElementById('adminName'),role=document.getElementById('adminRole'),button=document.getElementById('adminSessionButton'),avatar=document.getElementById('adminAvatar');if(!window.hmaSupabase){name.textContent='Admin belum login';role.textContent='Koneksi akun tidak tersedia';button.textContent='Masuk';return}const {data:{user}}=await window.hmaSupabase.auth.getUser();if(!user){name.textContent='Admin belum login';role.textContent='Gunakan akun perusahaan';button.textContent='Masuk';avatar.textContent='AR';return}const {data:profile}=await window.hmaSupabase.from('profiles').select('full_name,role').eq('id',user.id).single();if(profile?.role==='employee'){window.location.replace('employee.html');return}const displayName=profile?.full_name||user.user_metadata?.full_name||user.email;name.textContent=displayName;role.textContent=(profile?.role||'administrator').toUpperCase();avatar.textContent=displayName.split(/\s|@/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'AD';button.textContent='Keluar';}
document.getElementById('adminSessionButton').addEventListener('click',async()=>{const {data:{user}}=window.hmaSupabase?await window.hmaSupabase.auth.getUser():{data:{user:null}};if(user){await window.hmaSupabase.auth.signOut();await refreshAdminIdentity();returnToLogin();return}openAdminLogin()});
document.querySelectorAll('[data-close-admin-login]').forEach(x=>x.addEventListener('click',closeAdminLogin));
document.getElementById('adminLoginForm').addEventListener('submit',async e=>{e.preventDefault();const feedback=document.getElementById('adminLoginFeedback');feedback.hidden=true;if(!window.hmaSupabase){feedback.textContent='Koneksi akun belum tersedia. Muat ulang halaman lalu coba kembali.';feedback.hidden=false;return}const submit=e.currentTarget.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Memeriksa…';try{const identifier=document.getElementById('adminLoginEmail').value.trim();const email=/^HMA\d{3,}$/i.test(identifier)?internalAuthEmail(identifier):identifier.toLowerCase();const {data,error}=await window.hmaSupabase.auth.signInWithPassword({email,password:document.getElementById('adminLoginPassword').value});if(error||!data.user)throw error||new Error('Sesi login tidak berhasil dibuat.');const {data:profile,error:profileError}=await window.hmaSupabase.from('profiles').select('role').eq('id',data.user.id).single();if(profileError||!profile)throw new Error('Profil akun tidak ditemukan. Hubungi administrator.');if(profile.role==='employee'){window.location.replace('employee.html');return}if(!['admin','hr','finance'].includes(profile.role)){await window.hmaSupabase.auth.signOut();throw new Error('Akun ini tidak memiliki akses aplikasi.');}await refreshAdminIdentity();await loadTeam();finishLogin();notify('Login berhasil.')}catch(error){const message=error?.message==='Invalid login credentials'?'ID/email atau kata sandi tidak sesuai.':(error?.message||'Login gagal.');feedback.textContent=message;feedback.hidden=false;}finally{submit.disabled=false;submit.textContent='Masuk'}});
document.querySelectorAll('[data-password-toggle]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.passwordToggle),shown=input.type==='text';input.type=shown?'password':'text';button.textContent=shown?'◉':'◉̸';button.setAttribute('aria-label',shown?'Tampilkan kata sandi':'Sembunyikan kata sandi')}));
document.getElementById('resetAdminPassword').addEventListener('click',async()=>{const email=document.getElementById('adminLoginEmail').value.trim(),feedback=document.getElementById('adminLoginFeedback');feedback.hidden=true;if(!email||!email.includes('@')){feedback.textContent='Masukkan email administrator. Reset akun karyawan dilakukan dari menu Tim & Akses.';feedback.hidden=false;document.getElementById('adminLoginEmail').focus();return}if(!window.hmaSupabase){feedback.textContent='Koneksi akun belum tersedia.';feedback.hidden=false;return}const {error}=await window.hmaSupabase.auth.resetPasswordForEmail(email,{redirectTo:`${window.location.origin}${window.location.pathname}`});if(error){feedback.textContent=error.message||'Tautan reset belum dapat dikirim.';feedback.hidden=false;return}feedback.textContent='Tautan pemulihan telah dikirim. Periksa Inbox dan folder Spam.';feedback.style.background='#edf8f7';feedback.style.color='#087c74';feedback.hidden=false});
const passwordRecoveryModal=document.getElementById('passwordRecoveryModal');
function openPasswordRecovery(){passwordRecoveryModal.showModal();backdrop.classList.add('show')}
document.getElementById('passwordRecoveryForm').addEventListener('submit',async e=>{e.preventDefault();const feedback=document.getElementById('passwordRecoveryFeedback'),password=document.getElementById('newPassword').value,confirm=document.getElementById('confirmNewPassword').value;feedback.hidden=true;if(password!==confirm){feedback.textContent='Konfirmasi kata sandi belum sama.';feedback.hidden=false;return}const submit=e.currentTarget.querySelector('[type="submit"]');submit.disabled=true;try{const {error}=await window.hmaSupabase.auth.updateUser({password});if(error)throw error;passwordRecoveryModal.close();backdrop.classList.remove('show');notify('Kata sandi berhasil diperbarui. Silakan masuk kembali.')}catch(error){feedback.textContent=error.message||'Kata sandi belum dapat diperbarui.';feedback.hidden=false}finally{submit.disabled=false}});
document.addEventListener('click',e=>{const button=e.target.closest('.print-slip');if(!button)return;const employee=state.payroll.find(x=>x.id===button.dataset.id);if(!employee)return;const period=new Date(employee.periodStart+'T00:00:00').toLocaleDateString('id-ID',{month:'long',year:'numeric'}),amount=`Rp ${employee.netSalary.toLocaleString('id-ID')}`,printWindow=window.open('','_blank');printWindow.document.write(`<title>Slip Gaji ${escapeHtml(employee.name)}</title><style>body{font:14px Arial;padding:36px;color:#172a3a}.top{border-bottom:2px solid #148f88;padding-bottom:14px}h1{margin:0}table{width:100%;border-collapse:collapse;margin-top:25px}td{padding:12px;border-bottom:1px solid #ddd}.right{text-align:right}.total{font-weight:bold;font-size:17px}</style><div class="top"><h1>PT HAZARD MAJU ABADI</h1><p>SLIP GAJI KARYAWAN · ${escapeHtml(period)}</p></div><table><tr><td>Nama karyawan</td><td class="right">${escapeHtml(employee.name)}</td></tr><tr><td>ID karyawan</td><td class="right">${escapeHtml(employee.code)}</td></tr><tr><td>Hari kerja</td><td class="right">${employee.workDays} hari</td></tr><tr class="total"><td>TOTAL TAKE HOME PAY</td><td class="right">${amount}</td></tr></table><p style="margin-top:60px">Penerima, &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Finance / HRD</p>`);printWindow.document.close();printWindow.print()});
