document.getElementById('attendanceZoneForm').addEventListener('submit',saveAttendanceZone);
const quickRoutes={'Lihat laporan →':'transactions','Semua →':'reports','Lihat semua →':'reports','Kelola armada →':'fleets'};
document.querySelectorAll('button').forEach(button=>{if(button.matches('[data-view],[data-action],[data-open-modal],[data-open-import],[data-close-import],[data-close-modal],[data-close-report],[data-close-fuel],[data-close-salary],[data-close-employee],[data-close-admin-login],#pullReports,#downloadReport')||button.type==='submit')return;button.addEventListener('click',()=>{const label=button.textContent.trim();if(quickRoutes[label]){document.querySelector(`[data-view="${quickRoutes[label]}"]`).click();return}if(label.includes('Filter')){notify('Filter siap digunakan saat data backend terhubung.');return}if(label.includes('Pusat Bantuan')){notify('Pusat bantuan: hubungi administrator operasional.');return}if(label.includes('Tambah armada')||label.includes('Buat periode')){notify('Form ini akan tersedia setelah data master terhubung.');return}if(label==='⋮'||label.includes('Notifikasi')||label.includes('30 Agu')){notify('Tidak ada pembaruan baru.');return}notify('Fitur ini siap dihubungkan ke data operasional.')})});
backdrop.addEventListener('click',()=>{if(reportModal.open)closeReportModal();if(fuelModal.open)closeFuelModal();if(fleetModal.open)closeFleetModal();if(fuelTypeModal.open)closeFuelTypeModal();if(fuelPriceModal.open)closeFuelPriceModal();if(salaryModal.open)closeSalaryModal();if(employeeModal.open)closeEmployeeModal();if(employeeResetModal.open)closeEmployeeReset();if(importModal.open)closeImportModal();if(passwordRecoveryModal.open)passwordRecoveryModal.close();if(adminLoginModal.open)closeAdminLogin()});setDefaultReportDates();render();refreshAdminIdentity();loadFuelReports();loadFleets();loadReports();loadTransactions();loadAttendance();loadPayroll();loadTeam();loadEmployeeRequests();loadAttendanceZone();if(window.hmaSupabase)window.hmaSupabase.auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY')setTimeout(openPasswordRecovery,0);if(event==='SIGNED_OUT')setTimeout(returnToLogin,0);setTimeout(refreshAdminIdentity,0);if(event!=='SIGNED_OUT'){setTimeout(loadFuelReports,0);setTimeout(loadFleets,0);setTimeout(loadReports,0);setTimeout(loadTransactions,0);setTimeout(loadAttendance,0);setTimeout(loadPayroll,0);setTimeout(loadTeam,0);setTimeout(loadEmployeeRequests,0);setTimeout(loadAttendanceZone,0)}});setTimeout(async()=>{if(!await ensureAdminSession())openAdminLogin()},0);
function refreshOperationalSummary(){loadFuelReports();loadFleets();loadReports();loadTransactions();loadAttendance();loadPayroll();loadTeam();loadAttendanceZone()}
if(window.hmaSupabase){window.hmaSupabase.channel('hma-operational-summary').on('postgres_changes',{event:'*',schema:'public',table:'cash_transactions'},loadTransactions).on('postgres_changes',{event:'*',schema:'public',table:'attendance'},loadAttendance).on('postgres_changes',{event:'*',schema:'public',table:'attendance_zones'},loadAttendanceZone).on('postgres_changes',{event:'*',schema:'public',table:'employee_reports'},loadReports).on('postgres_changes',{event:'*',schema:'public',table:'fuel_logs'},loadFuelReports).on('postgres_changes',{event:'*',schema:'public',table:'payroll_records'},loadPayroll).on('postgres_changes',{event:'*',schema:'public',table:'vehicles'},loadFleets).on('postgres_changes',{event:'*',schema:'public',table:'employee_leave_requests'},loadEmployeeRequests).on('postgres_changes',{event:'*',schema:'public',table:'employee_cash_advances'},loadEmployeeRequests).subscribe();setInterval(refreshOperationalSummary,30000)}
